<?php use Luna\Core\Csrf; use Luna\Core\View; $token=View::e(Csrf::token()); ?>
<div class="page-intro"><div><span class="eyebrow">Supply chain</span><h1>Logistica e magazzino</h1><p>Giacenze disponibili, movimenti atomici, trasferimenti e picking con barcode.</p></div></div>
<section class="accounting-kpis"><article><span>Articoli a saldo</span><strong><?= count($balances) ?></strong></article><article><span>Valore scorte</span><strong><?= View::money(array_sum(array_map(fn($r)=>(float)$r['quantity']*(float)$r['average_cost'],$balances))) ?></strong></article><article><span>Picking aperti</span><strong><?= count(array_filter($picks,fn($r)=>$r['status']!=='COMPLETED')) ?></strong></article><article><span>Trasferimenti in transito</span><strong><?= count(array_filter($transfers,fn($r)=>$r['status']==='IN_TRANSIT')) ?></strong></article></section>
<div class="two-columns">
<section class="card form-card"><div class="card-header"><div><h2>Movimento manuale controllato</h2><p>Lo scarico non consente giacenze negative.</p></div></div><form method="post" action="/operations/logistics/movement" class="form-grid"><input type="hidden" name="_token" value="<?= $token ?>"><label class="field">Data<input type="date" name="movement_date" value="<?= date('Y-m-d') ?>" required></label><label class="field">Prodotto<select name="product_id" required><?php foreach($products as $p):?><option value="<?= (int)$p['id'] ?>"><?= View::e($p['code'].' · '.$p['name']) ?></option><?php endforeach;?></select></label><label class="field">Magazzino<select name="warehouse_id" required><?php foreach($warehouses as $w):?><option value="<?= (int)$w['id'] ?>"><?= View::e($w['code'].' · '.$w['name']) ?></option><?php endforeach;?></select></label><label class="field">Tipo<select name="movement_type"><option value="IN">Carico</option><option value="OUT">Scarico</option><option value="ADJUSTMENT">Rettifica +</option></select></label><label class="field">Quantità<input type="number" step="0.0001" min="0.0001" name="quantity" required></label><label class="field">Costo unitario<input type="number" step="0.0001" min="0" name="unit_cost"></label><label class="field full-width">Causale<input name="reason" required></label><div class="form-actions full-width"><button class="button primary">Registra movimento</button></div></form></section>
<section class="card form-card"><div class="card-header"><div><h2>Nuovo trasferimento</h2><p>Scarico e carico avvengono in due passaggi tracciati.</p></div></div><form method="post" action="/operations/logistics/transfers" class="form-grid"><input type="hidden" name="_token" value="<?= $token ?>"><label class="field">Data<input type="date" name="transfer_date" value="<?= date('Y-m-d') ?>"></label><label class="field">Origine<select name="source_warehouse_id"><?php foreach($warehouses as $w):?><option value="<?= (int)$w['id'] ?>"><?= View::e($w['code']) ?></option><?php endforeach;?></select></label><label class="field">Destinazione<select name="destination_warehouse_id"><?php foreach(array_reverse($warehouses) as $w):?><option value="<?= (int)$w['id'] ?>"><?= View::e($w['code']) ?></option><?php endforeach;?></select></label><label class="field">Prodotto<select name="lines[0][product_id]"><?php foreach($products as $p):?><option value="<?= (int)$p['id'] ?>"><?= View::e($p['code'].' · '.$p['name']) ?></option><?php endforeach;?></select></label><label class="field">Quantità<input type="number" step="0.0001" min="0.0001" name="lines[0][quantity]" required></label><label class="field">Note<input name="notes"></label><div class="form-actions full-width"><button class="button primary">Crea trasferimento</button></div></form></section>
</div>
<section class="card"><div class="card-header"><div><h2>Picking barcode</h2><p>La creazione impegna la merce; il completamento registra lo scarico.</p></div></div><form method="post" action="/operations/logistics/picks" class="form-grid"><input type="hidden" name="_token" value="<?= $token ?>"><label class="field">Ordine / DDT<select name="document_id"><?php foreach($orders as $o):?><option value="<?= (int)$o['id'] ?>"><?= View::e($o['number'].' · '.$o['counterparty_name']) ?></option><?php endforeach;?></select></label><label class="field">Magazzino<select name="warehouse_id"><?php foreach($warehouses as $w):?><option value="<?= (int)$w['id'] ?>"><?= View::e($w['code'].' · '.$w['name']) ?></option><?php endforeach;?></select></label><div class="form-actions"><button class="button primary">Crea lista</button></div></form><div class="table-wrap"><table><thead><tr><th>Lista</th><th>Documento</th><th>Magazzino</th><th>Avanzamento</th><th>Stato</th><th>Scansione / azioni</th></tr></thead><tbody><?php foreach($picks as $p):?><tr><td class="primary-cell"><?= View::e($p['pick_number']) ?></td><td><?= View::e($p['document_number']) ?></td><td><?= View::e($p['warehouse_code']) ?></td><td><?= View::e($p['picked_quantity'].' / '.$p['required_quantity']) ?></td><td><span class="badge status-<?= strtolower($p['status']) ?>"><?= View::e($p['status']) ?></span></td><td><div class="inline-actions"><?php if(in_array($p['status'],['OPEN','PICKING'],true)):?><form method="post" action="/operations/logistics/picks/<?= (int)$p['id'] ?>/scan" class="inline-form"><input type="hidden" name="_token" value="<?= $token ?>"><input name="barcode" placeholder="EAN / SKU" required><input type="number" name="quantity" value="1" min="0.0001" step="0.0001"><button class="button">Scansiona</button></form><form method="post" action="/operations/logistics/picks/<?= (int)$p['id'] ?>/complete"><input type="hidden" name="_token" value="<?= $token ?>"><button class="button primary">Completa</button></form><form method="post" action="/operations/logistics/picks/<?= (int)$p['id'] ?>/cancel" onsubmit="return confirm('Annullare il picking e liberare le quantità impegnate?')"><input type="hidden" name="_token" value="<?= $token ?>"><button class="button danger">Annulla</button></form><?php endif;?></div></td></tr><?php endforeach;?></tbody></table></div></section>
<section class="card"><div class="card-header"><h2>Trasferimenti</h2></div><div class="table-wrap"><table><thead><tr><th>Numero</th><th>Data</th><th>Da</th><th>A</th><th>Stato</th><th>Azioni</th></tr></thead><tbody><?php foreach($transfers as $t):?><tr><td class="primary-cell"><?= View::e($t['transfer_number']) ?></td><td><?= View::date($t['transfer_date']) ?></td><td><?= View::e($t['source_code']) ?></td><td><?= View::e($t['destination_code']) ?></td><td><span class="badge status-<?= strtolower($t['status']) ?>"><?= View::e($t['status']) ?></span></td><td><div class="inline-actions"><?php if($t['status']==='DRAFT'):?><form method="post" action="/operations/logistics/transfers/<?= (int)$t['id'] ?>/confirm"><input type="hidden" name="_token" value="<?= $token ?>"><button class="button">Conferma partenza</button></form><form method="post" action="/operations/logistics/transfers/<?= (int)$t['id'] ?>/cancel"><input type="hidden" name="_token" value="<?= $token ?>"><button class="button danger">Annulla</button></form><?php elseif($t['status']==='IN_TRANSIT'):?><form method="post" action="/operations/logistics/transfers/<?= (int)$t['id'] ?>/receive"><input type="hidden" name="_token" value="<?= $token ?>"><button class="button primary">Ricevi tutto</button></form><?php endif;?></div></td></tr><?php endforeach;?></tbody></table></div></section>
<section class="card"><div class="card-header"><h2>Giacenze</h2></div><div class="table-wrap"><table><thead><tr><th>Magazzino</th><th>Codice</th><th>Prodotto</th><th>Fisica</th><th>Impegnata</th><th>Disponibile</th><th>Costo medio</th></tr></thead><tbody><?php foreach($balances as $b):?><tr><td><?= View::e($b['warehouse_code']) ?></td><td><?= View::e($b['product_code']) ?></td><td class="primary-cell"><?= View::e($b['product_name']) ?></td><td><?= View::e($b['quantity']) ?></td><td><?= View::e($b['reserved_quantity']) ?></td><td><?= View::e($b['available']) ?></td><td><?= View::money($b['average_cost']) ?></td></tr><?php endforeach;?></tbody></table></div></section>
